CREATE OR REPLACE FUNCTION public.finance_invoice_asset_fingerprint(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT md5((v||jsonb_build_object('invoice',(v->'invoice')-'review_status'-'approved_by'-'approved_at'-'updated_at'))::text) $$;
REVOKE ALL ON FUNCTION public.finance_invoice_asset_fingerprint(jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_invoice_asset_fingerprint(jsonb) TO authenticated;
DO $$ DECLARE def text;n text;BEGIN FOREACH n IN ARRAY ARRAY['finance_invoice_asset_propose','finance_invoice_asset_approve'] LOOP SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=n;def:=replace(def,'md5(v::text)','public.finance_invoice_asset_fingerprint(v)');IF n='finance_invoice_asset_propose' THEN def:=replace(def,'asset:=finance_schedule_account', 'IF EXISTS(SELECT 1 FROM finance_entry_drafts WHERE tenant_id=t AND source_data->>''invoice''=i.id::text AND source_data ? ''invoice_asset_line'' AND status=''waiting'') THEN RAISE EXCEPTION ''Approve the existing invoice asset proposal before another line'';END IF;asset:=finance_schedule_account');END IF;EXECUTE def;END LOOP;END $$;